'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var isFloat64Array = require( '@stdlib/assert/is-float64array' );
var rffti = require( './../lib/rffti.js' );


// FIXTURES //

var nd = [ 120, 91, 54, 49, 32, 28, 24, 8, 4, 3, 2 ];


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof rffti, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function initializes FFT working arrays', function test( t ) {
	var ptr;
	var w;
	var i;
	var n;

	ptr = 1;
	for ( i = 0; i < nd.length; i++ ) {
		n = nd[ i ];
		w = new Float64Array( ( 2 * n ) + 15 );
		rffti( n, w, ptr );
		t.strictEqual( isFloat64Array( w ), true, 'returns expected value for n=' + n );
		t.notEqual( w[ ptr ], 0.0, 'modifies input array for n=' + n );
		t.notEqual( w[ n + ptr ], 0.0, 'modifies input array for n=' + n );
		ptr += ( 2 * n ) + 15;
	}
	t.end();
});
